const r = await tools.read({ file_path: "docs/CHANGELOG.md", offset: 1, limit: 40 });
const total = r.totalLines;
const tail = await tools.read({ file_path: "docs/CHANGELOG.md", offset: Math.max(1, total - 45), limit: 60 });
const git = await tools.bash({ command: "git rev-parse --is-inside-work-tree 2>&1; git status --short 2>&1 | head -20; git remote -v 2>&1 | head -5", description: "检查 git 仓库状态" });
return {
  totalLines: total,
  head: r.lines.map(l => `${l.number}: ${l.text}`).join("\n"),
  tail: tail.lines.map(l => `${l.number}: ${l.text}`).join("\n"),
  git: git.stdout.text
};
", "description": "读取变更日志格式并检查 git 状态"}

