const check = await tools.bash({
  command: "wc -l 个人心理报告.md 个人心理健康建议.md 个人心理健康提升方法.md && tail -20 docs/CHANGELOG.md",
  description: "校验文档行数与日志末尾"
});
const commit = await tools.bash({
  command: `git add "个人心理报告.md" "个人心理健康建议.md" "个人心理健康提升方法.md" docs/CHANGELOG.md "context/2026/10/30/13-06-23/对话.md" && git commit -m "docs: 新增个人心理报告、心理健康建议与提升方法" && git push 2>&1 | tail -5`,
  description: "提交并推送本次文档改动"
});
return { check: check.stdout.text, commit: commit.stdout.text, err: commit.stderr.text, code: commit.exitCode };
", "description": "校验文件后提交并推送"}

