  old_string: "- **Git 提交**：待提交\n\n---\n",
  new_string: "- **Git 提交**：`013e791 docs: 新增个人心理报告、心理健康建议与提升方法`；已推送至 `origin/main`。\n\n---\n"
});

const c = await tools.bash({
  command: `git add docs/CHANGELOG.md && git commit -m "docs: 补记心理文档任务的提交哈希" && git push 2>&1 | tail -3`,
  description: "补记提交哈希并推送"
});

return { edit: e.after.slice(-80), commit: c.stdout.text };
